def BA(poses, X, tids, support, tr, ref):
    n = len(poses)
    others = [i for i in range(n) if i != ref]
    lookup = {i: j for j, i in enumerate(others)}
    nc = 6 * len(others)
    x0 = np.r_[np.concatenate([vec(poses[i]) for i in others]), X.ravel()]
    ob = [obs(a['id']) for a in ledger()]
    pi = []
    fi = []
    uv = []
    for j, (t, frames) in enumerate(zip(tids, support)):
        for i in frames:
            pi.append(j)
            fi.append(i)
            uv.append(tr['xy'][t, i])
    pi, fi, uv = (np.array(pi), np.array(fi), np.array(uv))
    counts = np.bincount(fi, minlength=n)
    rglen = [len(ring_residual(poses[i], ob[i])) for i in range(n)]
    nf = len(fi)
    rows = 3 * nf + sum(rglen) + 6 * len(_FRONTEND_TEMPORAL)
    sp = lil_matrix((rows, len(x0)), dtype=int)
    for j, (point, frame) in enumerate(zip(pi, fi)):
        row = [2 * j, 2 * j + 1, 2 * nf + j]
        sp[row, nc + point * 3:nc + point * 3 + 3] = 1
        if frame != ref:
            sp[row, lookup[frame] * 6:lookup[frame] * 6 + 6] = 1
    row = 3 * nf
    for i, nn in enumerate(rglen):
        if i != ref:
            sp[row:row + nn, lookup[i] * 6:lookup[i] * 6 + 6] = 1
        row += nn
    for i, _temporal_j in _FRONTEND_TEMPORAL:
        for j in [i, _temporal_j]:
            if j != ref:
                sp[row:row + 6, lookup[j] * 6:lookup[j] * 6 + 6] = 1
        row += 6

    def decode(x):
        cur = poses.copy()
        for i in others:
            cur[i] = pose(x[lookup[i] * 6:lookup[i] * 6 + 6])
        return (cur, x[nc:].reshape(-1, 3))

    def residual(x):
        cur, P = decode(x)
        pc = np.einsum('ni,nij->nj', P[pi] - cur[fi, :3, 3], cur[fi, :3, :3])
        q = pc @ K.T
        den = np.where(abs(q[:, 2]) > 0.01, q[:, 2], 0.01)
        feat = (q[:, :2] / den[:, None] - uv).ravel()
        positive = 10 * np.maximum(0, 0.1 - pc[:, 2])
        out = [feat, positive]
        for i in range(n):
            out.append(ring_residual(cur[i], ob[i]) * np.sqrt(max(1, counts[i]) / max(1, rglen[i])))
        for i, _temporal_j in _FRONTEND_TEMPORAL:
            dc = cur[_temporal_j, :3, 3] - poses[_temporal_j, :3, 3] - (cur[i, :3, 3] - poses[i, :3, 3])
            r0 = Rotation.from_matrix(cur[i, :3, :3] @ poses[i, :3, :3].T).as_rotvec()
            r1 = Rotation.from_matrix(cur[_temporal_j, :3, :3] @ poses[_temporal_j, :3, :3].T).as_rotvec()
            out.append(np.r_[dc / 10.0, (r1 - r0) / np.deg2rad(30)])
        return np.concatenate(out)
    fit = least_squares(residual, x0, jac_sparsity=sp.tocsr(), loss='soft_l1', f_scale=1.0, max_nfev=cfg()['BA_max_nfev'], diff_step=1e-05, ftol=1e-05, xtol=1e-05, gtol=1e-05)
    cur, P = decode(fit.x)
    res = residual(fit.x)
    return (cur, P, dict(success=fit.success, nfev=fit.nfev, train_track_ids=tids, train_feature_residual=stats(res[:2 * nf]), training_soft_l1_objective=float(np.mean(2 * (np.sqrt(1 + res * res) - 1))), train_observations=nf, trained_points=len(X), optimized_reference=False, ring_model_static=True))
